// The Red Queen directory. Every entry is a tool we can point at a file we
// own (or are authorised to inspect), and every entry is labelled with what it
// does to that file: read it, emulate it, or attach to something live.
//
// Covers live in public/images/tools and are generated by
// `bun run covers` (scripts/make-covers.ts).

export type Category =
  | 'disassembly'
  | 'decompilation'
  | 'debugging'
  | 'dynamic'
  | 'formats'
  | 'hex'
  | 'forensics'
  | 'firmware'
  | 'network'
  | 'mobile'

// static  — reads bytes, never executes the sample
// sandbox — executes the sample inside an emulator or isolated runtime
// live    — attaches to a running process, device or network you control
export type Safety = 'static' | 'sandbox' | 'live'

export type Platform = 'Windows' | 'macOS' | 'Linux' | 'Web' | 'Android' | 'iOS'

export interface CategoryMeta {
  key: Category
  label: string
  short: string
  blurb: string
}

