export const bySlug = (slug: string) => tools.find((t) => t.slug === slug)
export const featured = tools.filter((t) => t.featured)
export const newest = [...tools].sort((a, b) => b.added.localeCompare(a.added))

export const categoryLabel = (key: Category) => categories.find((c) => c.key === key)?.label ?? key
export const countByCategory = (key: Category) => tools.filter((t) => t.category === key).length
export const countBySafety = (key: Safety) => tools.filter((t) => t.safety === key).length
